378	/// Export to a PDF.
379	fn export_pdf(document: &PagedDocument, config: &CompileConfig) -> SourceResult<()> {
380	    let options = pdf_options(config);
381	    let buffer = typst_pdf::pdf(document, &options)?;
382	    config
383	        .output
384	        .write(&buffer)
385	        .map_err(|err| eco_format!("failed to write PDF file ({err})"))
386	        .at(Span::detached())?;
